ALTER TABLE [RATE_MASTER] ADD CONSTRAINT [FK_RATE_MASTER_RATE_ID] FOREIGN KEY ([RATE_ID]) REFERENCES [RATE] ([ID]);
ALTER TABLE [STATUS_MASTER] ADD CONSTRAINT [FK_STATUS_MASTER_STATUS_CODE] FOREIGN KEY ([STATUS_CODE]) REFERENCES [STATUS] ([ID]);
ALTER TABLE [TRAN_DET] ADD CONSTRAINT [FK_TRAN_DET_TRANSACTION_ID] FOREIGN KEY ([TRANSACTION_ID]) REFERENCES [TRANSACTION] ([ID]);

